function estimateFps(cpuId, gpuId, ramId, gameId, res = '1080p', settings = 'ultra') {
  const cpu = byId(cpuId), gpu = byId(gpuId), ram = ramId ? byId(ramId) : null;
  const game = GAMES.find(g => g.id === gameId);
  if (!cpu || !gpu || !game) return 0;
  const gpuFactor = Math.pow(Math.max(gpu.perf, 5) / REF_GPU_PERF, game.gpuWeight);
  const cpuFactor = Math.pow(Math.max(cpu.perf, 5) / REF_CPU_PERF, 1 - game.gpuWeight);
  let fps = game.refFps * gpuFactor * cpuFactor;
  if (res === '1440p') fps *= game.res1440;
  else if (res === '4K') fps *= game.res4k;
  if (settings === 'medium') fps *= 1.45;
  if (ram && ram.specs.capacityGb < 16) fps *= 0.92;
  if (ram && ram.specs.capacityGb < 8) fps *= 0.85;
  return Math.max(1, Math.round(fps));
}
function estimateBuildFps(parts, gameId, res = '1080p', settings = 'ultra') {
  return estimateFps(parts.cpu, parts.gpu, parts.ram, gameId, res, settings);
}
function fpsVerdict(fps) {
  if (fps >= 120) return { label: 'Отлично', cls: 'ok' };
  if (fps >= 60) return { label: 'Комфортно', cls: 'ok' };
  if (fps >= 30) return { label: 'Играбельно', cls: 'warn' };
  return { label: 'Слабо', cls: 'err' };
}
function avgFps(parts, res = '1080p') {
  const vals = GAMES.map(g => estimateBuildFps(parts, g.id, res));
  return Math.round(vals.reduce((a, b) => a + b, 0) / vals.length);
}

// ---------- Генерация предложений (цен) — ленивая по городам ----------
function seededRand(seed) { let s = seed; return () => { s = (s * 9301 + 49297) % 233280; return s / 233280; }; }

const OFFERS = [];
const OFFER_INDEX = new Map();
const GENERATED_CITIES = new Set();
const NEW_STORES = STORES.filter(s => s.type === 'new');

function ensureCityOffers(cityId) {
  if (GENERATED_CITIES.has(cityId)) return;
  GENERATED_CITIES.add(cityId);
  const city = CITIES.find(c => c.id === cityId);
  if (!city) return;
  const citi = CITIES.indexOf(city);
  COMPONENTS.forEach((c, ci) => {
    const rnd = seededRand(1000 + ci * 137 + citi * 31);
    const storesHere = [...NEW_STORES].sort(() => rnd() - 0.5).slice(0, 2);
    storesHere.forEach(store => {
      const jitter = 0.97 + rnd() * 0.06;
      const price = Math.round(c.basePrice * store.coeff * city.coeff * jitter / 10) * 10;
      const oldPrice = rnd() > 0.6 ? Math.round(price * (1.08 + rnd() * 0.15) / 10) * 10 : null;
      const o = {
        componentId: c.id, storeId: store.id, regionId: city.id,
        price, oldPrice, condition: 'new',
        deliveryDays: city.id === 'online' ? 1 + Math.floor(rnd() * 5) : 0,
        deliveryPrice: city.id === 'online' ? (rnd() > 0.4 ? 0 : 290 + Math.floor(rnd() * 4) * 100) : 0,
        updated: `2026-11-${String(20 + Math.floor(rnd() * 6)).padStart(2,'0')}`,
      };
      OFFERS.push(o);
      const k = c.id + '|' + city.id;
      if (!OFFER_INDEX.has(k)) OFFER_INDEX.set(k, []);
      OFFER_INDEX.get(k).push(o);
    });
  });
  OFFER_INDEX.forEach(arr => arr.sort((a, b) => a.price - b.price));
}
// Предгенерация цен для ключевых городов выполняется в app.js — уже после
// подключения расширенного каталога (catalog.js), чтобы цены были у всех позиций.
const PREWARM_CITIES = ['nsk', 'msk', 'spb', 'online'];
function prewarmOffers() { PREWARM_CITIES.forEach(ensureCityOffers); }

const byId = id => COMPONENTS.find(c => c.id === id);
const cityById = id => CITIES.find(c => c.id === id);
const regionById = cityById;
const storeById = id => STORES.find(s => s.id === id);
const catById = id => CATEGORIES.find(c => c.id === id);
const fmt = n => n.toLocaleString('ru-RU') + ' ₽';

// Примерная оценка вторичного рынка. Это НЕ данные Авито/Юлы: реальная цена зависит
// от состояния, комплекта и продавца — пользователь должен проверять сам.
function usedEstimate(componentId, regionId) {
  const c = byId(componentId);
  if (!c) return null;
  const city = CITIES.find(x => x.id === regionId) || { coeff: 1, id: 'online' };
  const ci = CITIES.indexOf(city);
  const compIdx = COMPONENTS.indexOf(c);
  const rnd = seededRand(7777 + compIdx * 53 + (ci < 0 ? 0 : ci) * 17);
  const age = Math.max(0, 2026 - (c.year || 2020));
  // чем старше железо, тем сильнее падение вторички (но не ниже 35% и не выше 78% от новой)
  const coef = Math.min(0.78, Math.max(0.35, 0.70 - age * 0.035)) * (0.95 + rnd() * 0.1);
  return {
    price: Math.round(c.basePrice * coef * city.coeff / 10) * 10,
    estimate: true,
    note: 'Примерная цена вторичного рынка — проверяйте на Авито и Юле: состояние, комплект и продавец меняют цену в разы.',
  };
}

// Официальные магазины: только новые товары. БУ не выдаётся за предложение магазина.
function officialStoresFor(componentId, regionId) {
  return offersFor(componentId, { regionId, condition: 'new' });
}

function offersFor(componentId, { regionId = null, condition = null } = {}) {
  if (regionId) {
    ensureCityOffers(regionId);
    const arr = OFFER_INDEX.get(componentId + '|' + regionId) || [];
    return condition ? arr.filter(o => o.condition === condition) : arr.slice();
  }
  // Без города: только уже сгенерированные (чтобы не грузить все 600+ городов)
  return OFFERS.filter(o => o.componentId === componentId && (!condition || o.condition === condition))
    .sort((a, b) => a.price - b.price);
}
function minPrice(componentId, regionId, condition = 'new') {
  if (condition === 'used' || condition === 'any') {
    const est = usedEstimate(componentId, regionId);
    if (condition === 'used') return est ? est.price : null;
    const neu = minPrice(componentId, regionId, 'new');
    const cand = [neu, est ? est.price : null].filter(Boolean);
    return cand.length ? Math.min(...cand) : null;
  }
  const list = offersFor(componentId, { regionId, condition: 'new' });
  return list.length ? list[0].price : null;
}
function buildPrice(build, regionId, condition = 'new') {
  let total = 0, missing = 0;
  Object.values(build.parts).forEach(cid => {
    const comp = byId(cid);
    if (!comp) return;                       // неизвестный id — не ломаем расчёт
    const p = minPrice(cid, regionId, condition);
    if (p === null) { missing++; total += comp.basePrice; }
    else total += p;
  });
  return { total, missing };
}
// Сборка может быть неполной (деталь сняли в 3D) — считаем без падений
const PART0 = { perf: 0, work: 0, power: 0, specs: {} };
function buildPower(build) {
  const cpu = byId(build.parts.cpu) || PART0, gpu = byId(build.parts.gpu) || PART0;
  return (cpu.power || 0) + (gpu.power || 0) + 90;
}
function buildPerf(build) {
  const cpu = byId(build.parts.cpu) || PART0, gpu = byId(build.parts.gpu) || PART0;
  return Math.round(((cpu.perf || 0) * 0.35 + (gpu.perf || 0) * 0.65) * 10) / 10;
}
function buildWorkPerf(build) {
  const cpu = byId(build.parts.cpu) || PART0, gpu = byId(build.parts.gpu) || PART0;
  return Math.round(((cpu.work || 0) * 0.55 + (gpu.work || 0) * 0.45) * 10) / 10;
}

// ---------- Гибкий поиск ----------
const SEARCH_ALIASES = [
  { keys: ['видяха','видеокарта','видеокарты','gpu','графический'], cat: 'gpu' },
  { keys: ['проц','процессор','процессоры','cpu','цпу'], cat: 'cpu' },
  { keys: ['оперативка','оперативная','память','оператив','ram','озу'], cat: 'ram' },
  { keys: ['бп','блок питания','блок питания','psu','питание'], cat: 'psu' },
  { keys: ['кулер','охлаждение','охлаждение','вентилятор','cooling'], cat: 'cooling' },
  { keys: ['корпус','корпуса','case'], cat: 'case' },
  { keys: ['плата','материнская','материнка','motherboard','mb'], cat: 'motherboard' },
  // Для накопителей generic — только общие слова; hdd/nvme/sata — конкретные типы, их оставляем токенами
  { keys: ['ssd','накопитель','диск','hdd','жесткий','жесткий диск','nvme'], cat: 'ssd', generic: ['ssd','накопитель','диск'] },
];
function normalize(s) { return String(s || '').toLowerCase().replace(/ё/g, 'е').trim(); }
function compSearchText(c) {
  const specs = Object.values(c.specs).join(' ');
  const cat = catById(c.cat);
  return normalize(c.name + ' ' + c.brand + ' ' + (cat ? cat.name : c.cat) + ' ' + specs + ' ' + (c.aliases || []).join(' '));
}
function matchesQuery(c, query) {
  const q = normalize(query);
  if (!q) return true;
  const text = compSearchText(c);
  // Алиасы категорий: если запрос содержит слово-категорию, проверяем категорию
  // и исключаем эти слова из токенов (иначе «видяха» не найдётся в названии)
  const aliasTokens = new Set();
  for (const a of SEARCH_ALIASES) {
    if (a.keys.some(k => q.includes(k))) {
      if (c.cat !== a.cat) return false;
      (a.generic || a.keys).forEach(k => aliasTokens.add(k));
    }
  }
  const tokens = q.split(/\s+/).filter(Boolean).filter(t => ![...aliasTokens].some(k => k.includes(t) || t.includes(k)));
  return tokens.every(t => text.includes(t));
}
function searchComponents(query, { cat = 'all', brand = 'all', minPriceV = null, maxPriceV = null, yearFilter = 'all', cityId = null } = {}) {
  let list = COMPONENTS.filter(c => matchesQuery(c, query));
  if (cat !== 'all') list = list.filter(c => c.cat === cat);
  if (brand !== 'all') list = list.filter(c => c.brand === brand);
  if (yearFilter === 'new') list = list.filter(c => c.year >= 2020);
  if (yearFilter === 'old') list = list.filter(c => c.year < 2020);
  if (minPriceV !== null || maxPriceV !== null) {
    list = list.filter(c => {
      const p = (cityId ? minPrice(c.id, cityId, 'new') : null) ?? c.basePrice;
      if (minPriceV !== null && p < minPriceV) return false;
      if (maxPriceV !== null && p > maxPriceV) return false;
      return true;
    });
  }
  return list;
}

